"use strict";
module.exports = /*#__PURE__*/JSON.parse('[{"id":1,"common_name":"Rambutan","scientific_name":"Nephelium lappaceum L.","family":"Sapindaceae","location":"Parkiran","content":{"sky_section":{"headline":"The Hairy Sweetness","sub_headline":"Di balik penampilannya yang liar dan berantakan, tersimpan kemanisan yang murni. Pengingat alami bahwa nilai sejati seringkali tersembunyi di balik kulit yang kasar."},"canopy_section":{"title":"Manfaat Ekologis","description":"Pohon ini adalah \'Hotel Bintang Lima\' bagi semut rangrang dan lebah madu karena bunganya kaya nektar. Buahnya kaya Vitamin C dan serat."},"trunk_section":[{"type":"Sejarah","title":"Asal Usul","description":"Asli Asia Tenggara dan sudah dibudidayakan selama ribuan tahun. Namanya berasal dari kata melayu \'Rambut\'."},{"type":"Fakta Unik","title":"Kerabat Leci","description":"Bersaudara dekat dengan Leci dan Lengkeng (Family Sapindaceae). Bijinya mengandung lemak yang bisa dipakai membuat lilin atau sabun."},{"type":"Islamic Insight","title":"Filosofi Husnuzan","description":"Jangan tertipu penampilan luar yang kasar/berambut. Seperti mukmin, mungkin fisiknya sederhana, tapi hatinya manis dan bermanfaat."}],"root_section":{"description":"Pohon buah tropis dengan kulit berambut unik yang menyembunyikan daging buah putih manis."}}},{"id":2,"common_name":"Ketapang Kencana","scientific_name":"Terminalia mantaly","family":"Combretaceae","location":"Parkiran + Lapangan","content":{"sky_section":{"headline":"The Natural Parasol","sub_headline":"Arsitektur alam yang sempurna untuk perlindungan. Tajuknya yang berlapis mengajarkan kita seni melindungi orang lain tanpa mengharapkan imbalan apa pun."},"canopy_section":{"title":"Manfaat Ekologis","description":"Daun kecilnya sangat efektif menyaring polusi udara. Bentuk tajuknya melebar memberikan area teduh yang sangat luas."},"trunk_section":[{"type":"Asal","title":"Pendatang Madagaskar","description":"Berasal dari Madagaskar, namun sangat populer di Indonesia sebagai peneduh jalan modern."},{"type":"Arsitektur Alami","title":"Payung Bertingkat","description":"Rantingnya tumbuh mendatar secara alami membentuk lapisan rapi tanpa perlu dipangkas manusia."},{"type":"Islamic Insight","title":"Amal Jariyah","description":"Seperti payung yang melindungi orang dari panas, jadilah manusia yang kehadirannya selalu meneduhkan dan melindungi orang lain."}],"root_section":{"description":"Pohon peneduh elegan dengan struktur ranting bertingkat yang rapi."}}},{"id":3,"common_name":"Palem Putri","scientific_name":"Veitchia merrillii","family":"Arecaceae","location":"Parkiran","content":{"sky_section":{"headline":"The Christmas Palm","sub_headline":"Dinamai karena buah merahnya yang meriah di bulan Desember, palem ini membawa semangat perayaan dan keanggunan bahkan ke ruang yang paling sempit sekalipun."},"canopy_section":{"title":"Manfaat Lanskap","description":"Daunnya melengkung indah seperti mahkota. Sangat cocok ditanam di area sempit karena akarnya tidak merusak pondasi bangunan."},"trunk_section":[{"type":"Julukan","title":"Christmas Palm","description":"Sering disebut \'Christmas Palm\' karena buahnya merah cerah menggantung seperti hiasan Natal di bulan Desember."},{"type":"Fakta Fisik","title":"Batang Tunggal","description":"Memiliki batang tunggal (single trunk) yang bersih dan beruas-ruas, membuatnya tampak sangat rapi dan ningrat."},{"type":"Islamic Insight","title":"Keteguhan Iman","description":"Akar palem menghujam kuat ke bumi agar batangnya bisa lurus menjulang ke langit. Begitu juga iman, harus kuat agar amal bisa naik diterima Allah."}],"root_section":{"description":"Palem hias populer dengan buah merah yang cantik dan batang yang bersih."}}},{"id":4,"common_name":"Bunga Sepatu","scientific_name":"Hibiscus rosa-sinensis","family":"Malvaceae","location":"Parkiran","content":{"sky_section":{"headline":"The Natural Shoe Polish","sub_headline":"Lebih dari sekadar kelopak cantik. Sejarah membisikkan masa lalunya yang praktis di India, membuktikan bahwa keindahan dan kegunaan bisa hidup berdampingan dengan sempurna."},"canopy_section":{"title":"Manfaat Konsumsi","description":"Bunganya bisa dimakan (edible) atau diseduh menjadi teh herbal yang segar. Kaya antioksidan dan Vitamin C."},"trunk_section":[{"type":"Sejarah","title":"Asal Nama","description":"Kenapa disebut \'Bunga Sepatu\'? Di India kuno, kelopak bunganya diremas untuk menyemir sepatu kulit hitam agar mengkilap!"},{"type":"Sains","title":"Indikator Alami","description":"Air rebusan bunganya bisa berubah warna jika ditetesi asam (jeruk) atau basa (sabun). Coba buktikan di Lab IPA!"},{"type":"Islamic Insight","title":"Mekar Sehari","description":"Bunga ini hanya mekar 1 hari lalu layu. Dunia ini singkat (fana), maka manfaatkan \'waktu mekar\' (hidup) kita sebaik mungkin."}],"root_section":{"description":"Tanaman semak dengan bunga mencolok yang mekar sepanjang tahun."}}},{"id":5,"common_name":"Kamboja Kuning","scientific_name":"Plumeria rubra \'Lutea\'","family":"Apocynaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Immortal Fragrance","sub_headline":"Bunga yang menolak kehilangan esensinya. Bahkan ketika jatuh ke tanah, ia tetap menjaga wanginya, menyimbolkan kebaikan yang bertahan melampaui kesulitan."},"canopy_section":{"title":"Manfaat Ekologis","description":"Tanaman ini sangat tahan kekeringan (drought tolerant). Bunganya yang jatuh bisa dikeringkan untuk teh atau pewangi ruangan alami."},"trunk_section":[{"type":"Budaya","title":"Bukan Bunga Hantu","description":"Di Hawaii, bunga ini dirangkai menjadi kalung (Lei) untuk menyambut tamu kehormatan sebagai simbol dedikasi."},{"type":"Fakta Unik","title":"Wangi Awet","description":"Getahnya putih susu mengandung racun ringan tapi antiseptik. Bunganya tetap wangi berhari-hari meski sudah lepas dari pohon."},{"type":"Islamic Insight","title":"Keharuman Abadi","description":"Belajarlah dari Kamboja. Meski ia \'jatuh\' (sedang gagal/diuji), ia tetap wangi (berbuat baik) dan tidak membusuk (putus asa)."}],"root_section":{"description":"Pohon hias berbunga harum dengan batang sukulen yang artistik."}}},{"id":6,"common_name":"Tabebuya Kuning","scientific_name":"Handroanthus chrysotrichus","family":"Bignoniaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Sakura of Tropics","sub_headline":"Membawa keajaiban musim semi ke iklim tropis. Ketika panas menyerang, ia menjawabnya dengan keindahan, mengubah musim kering menjadi festival emas."},"canopy_section":{"title":"Manfaat Ekologis","description":"Pohon ini sangat tangguh menyerap polutan gas buang kendaraan. Akarnya dalam, tidak mudah tumbang dan tidak merusak jalan."},"trunk_section":[{"type":"Asal","title":"Hutan Amazon","description":"Berasal dari Brasil. Sering dikira Sakura Jepang, padahal berbeda spesies. Disebut \'Sakura Tropis\' karena mekarnya serempak."},{"type":"Sains","title":"Gugur Daun","description":"Saat musim kemarau ekstrem, ia menggugurkan semua daunnya dan menggantinya dengan ribuan bunga kuning serentak."},{"type":"Islamic Insight","title":"Hikmah Kesulitan","description":"Tabebuya justru mekar paling indah saat musim paling kering. Jadilah orang yang justru berprestasi saat kondisi sedang sulit."}],"root_section":{"description":"Pohon pelindung jalan yang berbunga kuning serentak di musim kemarau."}}},{"id":7,"common_name":"Ixora Merah","scientific_name":"Ixora coccinea","family":"Rubiaceae","location":"Lapangan + Taman","content":{"sky_section":{"headline":"The Honey Stick","sub_headline":"Harta karun masa kecil yang penuh nektar. Kemanisannya mengundang kupu-kupu dan manusia, mengingatkan kita bahwa kedermawanan selalu menarik teman-teman terbaik."},"canopy_section":{"title":"Manfaat Ekologis","description":"Disebut \'Butterfly Magnet\'. Karena nektarnya melimpah, tanaman ini selalu dikelilingi kupu-kupu yang membantu penyerbukan lingkungan."},"trunk_section":[{"type":"Nostalgia","title":"Jajanan Alami","description":"Anak-anak zaman dulu suka mencabut bunganya dan menghisap rasa manis (madu) yang ada di pangkalnya."},{"type":"Budaya","title":"Bunga Suci","description":"Di India, bunga ini dianggap suci dan sering dipakai dalam upacara keagamaan serta pengobatan tradisional (Ayurweda)."},{"type":"Islamic Insight","title":"Manisnya Akhlak","description":"Jadilah orang yang memiliki \'kemanisan\' akhlak dan ilmu, sehingga orang-orang shalih (seperti kupu-kupu) senang mendekatimu."}],"root_section":{"description":"Perdu hias populer dengan bunga majemuk berbentuk bola berwarna merah menyala."}}},{"id":8,"common_name":"Nusa Putih Indah","scientific_name":"Mussaenda sp.","family":"Rubiaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Master of Disguise","sub_headline":"Ilusi optik yang brilian. Dengan mengubah warna daunnya menjadi seperti bunga, ia mengajarkan bahwa terkadang peran pendukung justru adalah yang paling indah."},"canopy_section":{"title":"Manfaat Ekologis","description":"Daunnya berbulu halus. Tanaman ini sering dipakai sebagai pagar hidup dan penahan debu di pinggir jalan."},"trunk_section":[{"type":"Ilusi Optik","title":"Bukan Bunga Asli","description":"Apa yang kamu lihat sebagai \'Bunga Putih Besar\' itu palsu! Itu sebenarnya daun pelindung (bracts). Bunga aslinya kecil mungil di tengah."},{"type":"Asal","title":"Kebanggaan Nusantara","description":"Tanaman asli Asia Tenggara & Filipina. Nama \'Nusa Indah\' diberikan karena keindahannya menghias kepulauan nusantara."},{"type":"Islamic Insight","title":"Tawadhu","description":"Terkadang sosok utama (bunga asli) tak perlu tampil mencolok. Ia rela daun pelindungnya yang terlihat demi menjaga fungsi intinya."}],"root_section":{"description":"Tanaman hias dengan daun pelindung (bracts) yang mencolok warnanya."}}},{"id":9,"common_name":"Gardenia / Kaca Piring","scientific_name":"Gardenia jasminoides","family":"Rubiaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Aroma Queen","sub_headline":"Wewangian yang menaklukkan malam. Parfumnya adalah kemewahan, namun kelopaknya yang rapuh memperingatkan kita untuk selalu memperlakukan keindahan dengan kelembutan."},"canopy_section":{"title":"Manfaat Estetika","description":"Daunnya hijau pekat mengkilap (glossy) seperti kaca, makanya disebut \'Kaca Piring\'. Bunganya diekstrak untuk parfum kelas dunia."},"trunk_section":[{"type":"Fakta Unik","title":"Wangi Malam","description":"Wanginya makin kuat saat malam hari. Ini strategi alami untuk memanggil serangga penyerbuk nokturnal (aktif malam)."},{"type":"Sifat","title":"Sensitif","description":"Kelopak bunganya sangat \'baper\'. Jika disentuh tangan manusia yang hangat/kasar, ia akan cepat berubah cokelat (memar)."},{"type":"Islamic Insight","title":"Menjaga Hati","description":"Hati manusia itu sensitif seperti kelopak Gardenia. Berlemah-lembutlah dalam bicara agar tidak \'mememarkan\' hati saudaramu."}],"root_section":{"description":"Perdu berbunga putih bersih dengan aroma yang sangat harum dan daun mengkilap."}}},{"id":10,"common_name":"Pucuk Merah","scientific_name":"Syzygium myrtifolium","family":"Myrtaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Chameleon Plant","sub_headline":"Pelajaran hidup tentang transformasi. Dari merah yang berapi-api saat muda hingga hijau yang meneduhkan saat dewasa, ia menunjukkan keindahan di setiap fase perjalanan hidup."},"canopy_section":{"title":"Manfaat Ekologis","description":"Sangat efektif menyerap CO2 (Karbondioksida). Akar tunggangnya kuat menahan tanah agar tidak longsor."},"trunk_section":[{"type":"Sains","title":"Kenapa Merah?","description":"Daun mudanya mengandung antosianin (zat warna merah) untuk melindunginya dari sengatan matahari karena jaringannya belum kuat."},{"type":"Siklus","title":"Tiga Warna","description":"Memiliki gradasi 3 warna: Merah (Muda) -> Jingga/Cokelat (Remaja) -> Hijau (Dewasa) seiring bertambahnya usia daun."},{"type":"Islamic Insight","title":"Fase Kehidupan","description":"Warna daunnya mirip fase manusia: Semangat berapi-api saat muda (merah), lalu menjadi matang, tenang, dan meneduhkan saat tua (hijau)."}],"root_section":{"description":"Tanaman hias populer yang tunas daun barunya selalu berwarna merah cerah."}}},{"id":11,"common_name":"Bunga Kertas","scientific_name":"Bougainvillea spectabilis","family":"Nyctaginaceae","location":"Lapangan","content":{"sky_section":{"headline":"The Drought Survivor","sub_headline":"Keindahan yang lahir dari perjuangan. Ia membuktikan bahwa masa-masa sulit (kering) tidak harus menghancurkan kita; terkadang, itulah yang kita butuhkan untuk mekar paling cerah."},"canopy_section":{"title":"Manfaat Ekologis","description":"Tanaman paling tangguh! Tahan panas ekstrem dan polusi tinggi. Duri-durinya menjadi tempat aman bagi burung kecil membuat sarang."},"trunk_section":[{"type":"Sejarah","title":"Penjelajah","description":"Asal dari Brasil, dinamai menurut penjelajah Prancis, Louis Antoine de Bougainville yang menemukannya."},{"type":"Tips Perawatan","title":"Butuh Stres","description":"Malas berbunga? Jangan terlalu sering disiram! Tanaman ini butuh \'stres air\' (kering) untuk memicu mekarnya bunga yang lebat."},{"type":"Islamic Insight","title":"Hikmah Ujian","description":"Kadang Allah memberi \'masa sulit\' (kekeringan) bukan untuk menjatuhkan, tapi untuk memunculkan potensi terbaik (bunga) dari diri kita."}],"root_section":{"description":"Tanaman merambat berduri dengan seludang bunga warna-warni setipis kertas."}}},{"id":12,"common_name":"Aralera / Palem Kuning","scientific_name":"Dypsis lutescens","family":"Arecaceae","location":"Lapangan","content":{"sky_section":{"headline":"NASA\'s Air Purifier","sub_headline":"Penjaga napas kita yang sunyi. Bekerja diam-diam menetralkan racun udara, ia mengingatkan bahwa kontribusi paling berharga seringkali adalah yang tidak kasat mata."},"canopy_section":{"title":"Manfaat Kesehatan","description":"Pelepah daunnya berwarna kuning keemasan. Bisa ditanam indoor dan berfungsi melembabkan udara kering (humidifier alami)."},"trunk_section":[{"type":"Sains","title":"NASA Approved","description":"Studi NASA menobatkannya sebagai salah satu tanaman terbaik penyerap racun udara (seperti Xylene & Toluene)."},{"type":"Julukan","title":"Butterfly Palm","description":"Asli dari Madagaskar. Sering disebut \'Butterfly Palm\' karena daunnya melengkung ke atas mirip sayap kupu-kupu."},{"type":"Islamic Insight","title":"Pembersih Lingkungan","description":"Jadilah seperti Palem Kuning. Kehadirannya bisa menetralisir suasana \'beracun\' (amarah/konflik) di sekitarnya menjadi sejuk dan damai."}],"root_section":{"description":"Palem berumpun dengan pelepah berwarna kuning cerah khas dan daun menyirip."}}},{"id":13,"common_name":"Pohon Pelangi","scientific_name":"Eucalyptus deglupta","family":"Myrtaceae","location":"Lapangan + Taman","content":{"sky_section":{"headline":"The Living Painting","sub_headline":"Kanvas alam dalam satu batang pohon. Warna-warninya yang selalu berubah merayakan keberagaman, menunjukkan bahwa menjadi berbeda itulah yang membuat hidup menjadi mahakarya."},"canopy_section":{"title":"Manfaat Ekonomi","description":"Daunnya beraroma khas minyak kayu putih jika diremas. Pohon ini tumbuh sangat cepat dan menjadi bahan baku kertas berkualitas."},"trunk_section":[{"type":"Fenomena","title":"Bukan Dicat!","description":"Kulitnya mengelupas di waktu berbeda, menampilkan lapisan dalam berwarna hijau, biru, ungu, jingga, lalu cokelat secara alami."},{"type":"Habitat","title":"Asli Tropis","description":"Ini adalah satu-satunya spesies Eucalyptus yang asli tumbuh di hutan hujan tropis (Papua, Maluku, Filipina), bukan Australia."},{"type":"Islamic Insight","title":"Keberagaman","description":"Allah menciptakan warna-warni berbeda pada satu batang untuk keindahan. Begitu juga manusia, berbeda suku bangsa untuk saling melengkapi."}],"root_section":{"description":"Pohon raksasa dengan kulit batang berwarna-warni alami yang memukau."}}},{"id":14,"common_name":"Sambang Dara","scientific_name":"Excoecaria cochinchinensis","family":"Euphorbiaceae","location":"Taman","content":{"sky_section":{"headline":"The Two-Faced Leaf","sub_headline":"Dualitas warna yang sempurna. Hijau yang tenang di atas, merah yang membara di bawah—simbol menjaga ketenangan lahiriah sambil memegang teguh semangat di dalam jiwa."},"canopy_section":{"title":"Manfaat Medis","description":"Sering dijadikan tanaman obat tradisional untuk menghentikan pendarahan dan obat gatal (namun harus dengan resep ahli karena beracun)."},"trunk_section":[{"type":"Visual","title":"Daun Dua Muka","description":"Sisi atasnya berwarna hijau mengkilap, tapi jika dibalik, sisi bawahnya berwarna merah darah (blood red)."},{"type":"Peringatan","title":"Beracun","description":"Hati-hati! Getah tanaman ini beracun dan bisa menyebabkan iritasi mata atau kulit. Jangan dipetik sembarangan."},{"type":"Islamic Insight","title":"Zahir & Batin","description":"Simbol keseimbangan muslim. Tampak sejuk, tenang, beradab (hijau) di luar, namun memiliki semangat juang membara (merah) di dalam jiwa."}],"root_section":{"description":"Perdu unik dengan daun yang memiliki dua warna kontras (atas hijau, bawah merah)."}}},{"id":15,"common_name":"Cempedak","scientific_name":"Artocarpus integer","family":"Moraceae","location":"Taman","content":{"sky_section":{"headline":"The King of Aroma","sub_headline":"Kehadiran yang tidak bisa diabaikan. Seperti integritas sejati, karakter kuatnya membuat dirinya dikenal tanpa perlu berteriak."},"canopy_section":{"title":"Manfaat Konsumsi","description":"Buahnya manis dan lembut, bijinya pun enak dimakan setelah direbus/goreng. Daunnya lebar, bagus untuk peneduh."},"trunk_section":[{"type":"Perbedaan","title":"Sepupu Nangka","description":"Mirip Nangka tapi beda. Cempedak punya aroma jauh lebih menyengat/kuat, kulitnya lebih tipis, dan tekstur buahnya lebih lembek."},{"type":"Kegunaan","title":"Kayu Kuat","description":"Kayunya berwarna kuning cerah dan sangat kuat terhadap rayap. Sering dipakai untuk tiang rumah atau bahan perahu."},{"type":"Islamic Insight","title":"Kualitas Diri","description":"Aroma cempedak tak bisa disembunyikan. Kebaikan orang berilmu dan berakhlak mulia akan \'tercium\' orang banyak tanpa perlu pamer."}],"root_section":{"description":"Pohon buah tropis dengan aroma khas yang kuat dan kayu berkualitas."}}},{"id":16,"common_name":"Anting Putri","scientific_name":"Wrightia religiosa","family":"Apocynaceae","location":"Taman","content":{"sky_section":{"headline":"The Hanging Beauty","sub_headline":"Keanggunan dalam kerendahan hati. Dengan bunga yang menunduk ke bumi, ia mengajarkan bahwa elegansi sejati terletak pada sikap membumi, setinggi apa pun kita tumbuh."},"canopy_section":{"title":"Karakteristik","description":"Daunnya hijau cerah kekuningan. Sangat rajin berbunga sepanjang tahun dan tahan terhadap pemangkasan ekstrem."},"trunk_section":[{"type":"Hobi","title":"Primadona Bonsai","description":"Batangnya lentur, mudah dibentuk, dan memiliki karakter kulit kayu yang terkesan \'tua\' dan artistik."},{"type":"Unik","title":"Bunga Terbalik","description":"Unik karena bunganya tumbuh menggantung ke bawah (seperti anting-anting) dengan aroma wangi lembut."},{"type":"Islamic Insight","title":"Ilmu Padi","description":"Semakin berisi semakin merunduk. Posisi bunga yang selalu menunduk mengajarkan: semakin cantik/pintar kita, harus semakin rendah hati."}],"root_section":{"description":"Tanaman hias populer untuk bonsai dengan bunga putih kecil menggantung."}}},{"id":17,"common_name":"Antidisentri / Asam Belanda","scientific_name":"Pithecellobium dulce","family":"Fabaceae","location":"Taman","content":{"sky_section":{"headline":"The Survival Tree","sub_headline":"Tangguh di luar, menyembuhkan di dalam. Pejuang dunia tanaman yang mengubah pertahanan dirinya yang pahit menjadi penawar racun bagi orang lain."},"canopy_section":{"title":"Manfaat Konsumsi","description":"Buahnya unik: saat matang kulitnya merah merekah, dagingnya putih, rasanya manis-asam-sepat. Sangat disukai burung liar."},"trunk_section":[{"type":"Medis","title":"Obat Disentri","description":"Sesuai namanya, kulit batang dan daunnya mengandung zat tanin tinggi yang ampuh mengobati penyakit disentri (diare parah) secara tradisional."},{"type":"Karakter","title":"Tahan Banting","description":"Mampu hidup di tanah gersang dan panas. Batangnya berduri tajam sebagai pertahanan diri."},{"type":"Islamic Insight","title":"Obat itu Pahit","description":"Rasa kulit kayunya pahit dan sepat, tapi menyembuhkan. Terkadang nasihat kebenaran itu pahit didengar, namun itulah obat bagi penyakit hati."}],"root_section":{"description":"Pohon tangguh berduri dengan buah yang dapat dimakan dan khasiat obat."}}}]');

